"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[690],{196:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>hw-07-metric-bayes</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="домашняя-работа-7-обобщённый-метрический-классификатор-и-stolp">Домашняя\nработа 7. Обобщённый метрический классификатор и STOLP</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>К семинару</td>\n<td>занятие 7 — Метрические и байесовские методы классификации</td>\n</tr>\n<tr>\n<td>Опора</td>\n<td>материал семинара 7 и лекций до него</td>\n</tr>\n<tr>\n<td>Ожидаемое время</td>\n<td>3–4 часа</td>\n</tr>\n</tbody>\n</table>\n<p>На занятии мы пользовались <code>KNeighborsClassifier</code>. Дома\nвыяснится, что kNN, парзеновские окна и метод потенциальных функций —\nэто <strong>одна формула</strong> с разной весовой функцией: реализовав\nеё один раз, вы получите все пять методов сразу. Во второй задаче —\nотбор эталонов, который сокращает выборку в десятки раз, не теряя\nкачества.</p>\n<h2 id="что-нужно-сдать">Что нужно сдать</h2>\n<p>Заполненный ноутбук, в котором:</p>\n<ol>\n<li>выполнены все ячейки с <code># TODO</code>, код исполняется сверху\nвниз без ошибок в свежем ядре (Kernel → Restart &amp; Run All);</li>\n<li>под каждым заданием заполнена ячейка <strong>Вывод</strong> — своими\nсловами;</li>\n<li>графики подписаны: заголовок, оси, легенда;</li>\n<li>вариант ваш собственный (ячейка ниже).</li>\n</ol>\n<blockquote>\n<p>Списывание видно сразу: у каждого студента свой датасет и свой набор\nметодов.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> make_blobs</span>\n<span id="cb1-47"><a href="#cb1-47" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split</span>\n<span id="cb1-48"><a href="#cb1-48" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.neighbors <span class="im">import</span> KNeighborsClassifier</span>\n<span id="cb1-49"><a href="#cb1-49" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> StandardScaler</span></code></pre></div>\n</div>\n<div id="cell002" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell003" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">7</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell004" class="cell markdown">\n<hr />\n<h1 id="задача-1-пять-методов--одна-формула">Задача 1. Пять методов —\nодна формула</h1>\n<p>Определение 6.1 задаёт классификатор через веса соседей:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mrow><mi>arg</mi><mo>⁡</mo></mrow><munder><mi>max</mi><mi>k</mi></munder><munder><mo>∑</mo><mi>i</mi></munder><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">[</mo><msub><mi>y</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>i</mi><mo stretchy="false" form="postfix">)</mo></mrow></msub><mo>=</mo><mi>k</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">]</mo><mspace width="0.167em"></mspace><mi>w</mi><mo stretchy="false" form="prefix">(</mo><mi>i</mi><mo>,</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\na(x) = \\arg\\max_k\\sum_{i}\\bigl[y_{(i)} = k\\bigr]\\,w(i, x).\n</annotation></semantics></math></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<thead>\n<tr>\n<th>метод</th>\n<th>вес\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>w</mi><mo stretchy="false" form="prefix">(</mo><mi>i</mi><mo>,</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">w(i,x)</annotation></semantics></math></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nближайших соседей</td>\n<td><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">[</mo><mi>i</mi><mo>≤</mo><mi>k</mi><mo stretchy="false" form="postfix">]</mo></mrow><annotation encoding="application/x-tex">[i \\le k]</annotation></semantics></math></td>\n</tr>\n<tr>\n<td>kNN с весами</td>\n<td><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">[</mo><mi>i</mi><mo>≤</mo><mi>k</mi><mo stretchy="false" form="postfix">]</mo><mspace width="0.167em"></mspace><msup><mi>q</mi><mrow><mspace width="0.167em"></mspace><mi>i</mi></mrow></msup></mrow><annotation encoding="application/x-tex">[i \\le k]\\,q^{\\,i}</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>q</mi><mo>∈</mo><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">q\\in(0,1)</annotation></semantics></math></td>\n</tr>\n<tr>\n<td>парзеновское окно ширины\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>h</mi><annotation encoding="application/x-tex">h</annotation></semantics></math></td>\n<td><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mi>ρ</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><msub><mi>x</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>i</mi><mo stretchy="false" form="postfix">)</mo></mrow></msub><mo stretchy="false" form="postfix">)</mo><mi>/</mi><mi>h</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">K\\bigl(\\rho(x,x_{(i)})/h\\bigr)</annotation></semantics></math></td>\n</tr>\n<tr>\n<td>парзеновское окно переменной ширины</td>\n<td><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mi>ρ</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><msub><mi>x</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>i</mi><mo stretchy="false" form="postfix">)</mo></mrow></msub><mo stretchy="false" form="postfix">)</mo><mi>/</mi><mi>ρ</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><msub><mi>x</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>k</mi><mo>+</mo><mn>1</mn><mo stretchy="false" form="postfix">)</mo></mrow></msub><mo stretchy="false" form="postfix">)</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">K\\bigl(\\rho(x,x_{(i)})/\\rho(x,x_{(k+1)})\\bigr)</annotation></semantics></math></td>\n</tr>\n<tr>\n<td>потенциальные функции</td>\n<td><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>γ</mi><mi>i</mi></msub><mspace width="0.167em"></mspace><mi>K</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mi>ρ</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mi>/</mi><mi>h</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\gamma_i\\,K\\bigl(\\rho(x,x_i)/h\\bigr)</annotation></semantics></math></td>\n</tr>\n</tbody>\n</table>\n<p>Ваш вариант: <code>variant[&quot;metric_method&quot;]</code>, ядро\n<code>variant[&quot;kernel&quot;]</code>, метрика\n<code>variant[&quot;distance&quot;]</code>. Реализуйте <strong>один</strong> класс\nс параметром-методом.</p>\n</div>\n<div id="cell005" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a>KERNELS <span class="op">=</span> {</span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;прямоугольное&quot;</span>: <span class="kw">lambda</span> r: (np.<span class="bu">abs</span>(r) <span class="op">&lt;=</span> <span class="dv">1</span>) <span class="op">*</span> <span class="fl">0.5</span>,</span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;треугольное&quot;</span>: <span class="kw">lambda</span> r: np.maximum(<span class="fl">0.0</span>, <span class="dv">1</span> <span class="op">-</span> np.<span class="bu">abs</span>(r)),</span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;Епанечникова&quot;</span>: <span class="kw">lambda</span> r: np.maximum(<span class="fl">0.0</span>, <span class="fl">0.75</span> <span class="op">*</span> (<span class="dv">1</span> <span class="op">-</span> r <span class="op">**</span> <span class="dv">2</span>)),</span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;квартическое&quot;</span>: <span class="kw">lambda</span> r: np.maximum(<span class="fl">0.0</span>, (<span class="dv">15</span> <span class="op">/</span> <span class="dv">16</span>) <span class="op">*</span> (<span class="dv">1</span> <span class="op">-</span> r <span class="op">**</span> <span class="dv">2</span>) <span class="op">**</span> <span class="dv">2</span>),</span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;гауссовское&quot;</span>: <span class="kw">lambda</span> r: np.exp(<span class="op">-</span><span class="fl">0.5</span> <span class="op">*</span> r <span class="op">**</span> <span class="dv">2</span>) <span class="op">/</span> np.sqrt(<span class="dv">2</span> <span class="op">*</span> np.pi),</span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a>}</span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-9"><a href="#cb3-9" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: словарь DISTANCES с четырьмя метриками (евклидова -- через тождество</span></span>\n<span id="cb3-10"><a href="#cb3-10" aria-hidden="true" tabindex="-1"></a><span class="co">#       из занятия 1, чтобы не было тройного цикла).</span></span>\n<span id="cb3-11"><a href="#cb3-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-12"><a href="#cb3-12" aria-hidden="true" tabindex="-1"></a><span class="kw">class</span> MetricClassifier:</span>\n<span id="cb3-13"><a href="#cb3-13" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Обобщённый метрический классификатор (опр. 6.1).</span></span>\n<span id="cb3-14"><a href="#cb3-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-15"><a href="#cb3-15" aria-hidden="true" tabindex="-1"></a><span class="co">    Один класс, пять методов -- различаются ТОЛЬКО функцией веса w(i, x):</span></span>\n<span id="cb3-16"><a href="#cb3-16" aria-hidden="true" tabindex="-1"></a><span class="co">      &#39;knn&#39;             : [i &lt;= k]</span></span>\n<span id="cb3-17"><a href="#cb3-17" aria-hidden="true" tabindex="-1"></a><span class="co">      &#39;knn_weighted&#39;    : [i &lt;= k] q^i</span></span>\n<span id="cb3-18"><a href="#cb3-18" aria-hidden="true" tabindex="-1"></a><span class="co">      &#39;parzen_fixed&#39;    : K(rho / h)</span></span>\n<span id="cb3-19"><a href="#cb3-19" aria-hidden="true" tabindex="-1"></a><span class="co">      &#39;parzen_variable&#39; : K(rho / rho_(k+1))</span></span>\n<span id="cb3-20"><a href="#cb3-20" aria-hidden="true" tabindex="-1"></a><span class="co">      &#39;potential&#39;       : gamma_i K(rho / h)</span></span>\n<span id="cb3-21"><a href="#cb3-21" aria-hidden="true" tabindex="-1"></a><span class="co">    Подсказка: номер соседа i получается двойным argsort матрицы расстояний.</span></span>\n<span id="cb3-22"><a href="#cb3-22" aria-hidden="true" tabindex="-1"></a><span class="co">    Класс должен наследоваться от sklearn.base.BaseEstimator и ClassifierMixin,</span></span>\n<span id="cb3-23"><a href="#cb3-23" aria-hidden="true" tabindex="-1"></a><span class="co">    иначе его нельзя передать в cross_val_score.</span></span>\n<span id="cb3-24"><a href="#cb3-24" aria-hidden="true" tabindex="-1"></a><span class="co">    Нужны методы: fit(X, y, gamma=None), decision(X), predict(X).</span></span>\n<span id="cb3-25"><a href="#cb3-25" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb3-26"><a href="#cb3-26" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span></span>\n<span id="cb3-27"><a href="#cb3-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-28"><a href="#cb3-28" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-29"><a href="#cb3-29" aria-hidden="true" tabindex="-1"></a>METHOD_KEY <span class="op">=</span> {</span>\n<span id="cb3-30"><a href="#cb3-30" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;kNN с равными весами&quot;</span>: <span class="st">&quot;knn&quot;</span>,</span>\n<span id="cb3-31"><a href="#cb3-31" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;kNN с весами w(i) = q^i&quot;</span>: <span class="st">&quot;knn_weighted&quot;</span>,</span>\n<span id="cb3-32"><a href="#cb3-32" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;парзеновское окно фиксированной ширины&quot;</span>: <span class="st">&quot;parzen_fixed&quot;</span>,</span>\n<span id="cb3-33"><a href="#cb3-33" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;парзеновское окно переменной ширины&quot;</span>: <span class="st">&quot;parzen_variable&quot;</span>,</span>\n<span id="cb3-34"><a href="#cb3-34" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;метод потенциальных функций&quot;</span>: <span class="st">&quot;potential&quot;</span>,</span>\n<span id="cb3-35"><a href="#cb3-35" aria-hidden="true" tabindex="-1"></a>}</span>\n<span id="cb3-36"><a href="#cb3-36" aria-hidden="true" tabindex="-1"></a>my_method <span class="op">=</span> METHOD_KEY[variant[<span class="st">&quot;metric_method&quot;</span>]]</span></code></pre></div>\n</div>\n<div id="cell006" class="cell markdown">\n<h3 id="задание-11-все-пять-на-одной-картинке">Задание 1.1. Все пять на\nодной картинке</h3>\n<p>Сверьте свой <code>knn</code> со <code>sklearn</code> (предсказания\nобязаны совпасть полностью) и покажите границы решения всех пяти методов\nпри одном и том же ядре.</p>\n</div>\n<div id="cell007" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a>Xm, ym <span class="op">=</span> make_blobs(n_samples<span class="op">=</span><span class="dv">220</span>, centers<span class="op">=</span><span class="dv">3</span>, cluster_std<span class="op">=</span><span class="fl">1.6</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a>Xm <span class="op">=</span> StandardScaler().fit_transform(Xm)</span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a>Xa, Xv, ya, yv <span class="op">=</span> train_test_split(Xm, ym, test_size<span class="op">=</span><span class="fl">0.35</span>, stratify<span class="op">=</span>ym,</span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a>                                  random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) сверьте свой knn(5) с KNeighborsClassifier(5) -- предсказания</span></span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a><span class="co">#          должны совпасть полностью;</span></span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) постройте границы решения всех пяти методов на одном рисунке</span></span>\n<span id="cb4-9"><a href="#cb4-9" aria-hidden="true" tabindex="-1"></a><span class="co">#          (knn k=5; knn_weighted k=15, q=0.75; parzen_fixed h=0.6;</span></span>\n<span id="cb4-10"><a href="#cb4-10" aria-hidden="true" tabindex="-1"></a><span class="co">#           parzen_variable k=10; potential h=0.6).</span></span></code></pre></div>\n</div>\n<div id="cell008" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Чем отличаются границы разных весовых\nфункций? Что происходит с парзеновским окном фиксированной ширины в\nразреженной области выборки?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell009" class="cell markdown">\n<hr />\n<h1 id="задача-2-отступ-и-отбор-эталонов-stolp">Задача 2. Отступ и отбор\nэталонов (STOLP)</h1>\n<p>Определение 6.4: отступ объекта в метрическом классификаторе —</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msub><mi mathvariant="normal">Γ</mi><msub><mi>y</mi><mi>i</mi></msub></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>−</mo><munder><mi>max</mi><mrow><mi>k</mi><mo>≠</mo><msub><mi>y</mi><mi>i</mi></msub></mrow></munder><msub><mi mathvariant="normal">Γ</mi><mi>k</mi></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\nM(x_i) = \\Gamma_{y_i}(x_i) - \\max_{k \\ne y_i}\\Gamma_k(x_i).\n</annotation></semantics></math></p>\n<p>По величине отступа объекты делятся на эталонные\n(<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mo>≫</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">M \\gg 0</annotation></semantics></math>),\nнеинформативные, пограничные\n(<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mo>≈</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">M \\approx 0</annotation></semantics></math>),\nошибочные\n(<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mo>&lt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">M &lt; 0</annotation></semantics></math>)\nи шумовые\n(<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mo>≪</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">M \\ll 0</annotation></semantics></math>).\nАлгоритм STOLP отбирает небольшое подмножество эталонов, выбрасывая шум\nи «неинформативную массовку».</p>\n</div>\n<div id="cell010" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> margins(clf, X, y):</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;M(x_i) = Gamma_{y_i}(x_i) - max_{k != y_i} Gamma_k(x_i).</span></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a><span class="co">    Подсказка: возьмите clf.decision(X), выньте столбец своего класса,</span></span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a><span class="co">    в копии матрицы поставьте -inf на месте своего класса и возьмите максимум.</span></span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> stolp(X, y, delta<span class="op">=</span><span class="fl">0.0</span>, max_errors<span class="op">=</span><span class="fl">0.01</span>, k<span class="op">=</span><span class="dv">5</span>, kernel<span class="op">=</span><span class="st">&quot;Епанечникова&quot;</span>):</span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;STOLP:</span></span>\n<span id="cb5-12"><a href="#cb5-12" aria-hidden="true" tabindex="-1"></a><span class="co">       1) посчитать отступы по классификатору на ПОЛНОЙ выборке и выбросить</span></span>\n<span id="cb5-13"><a href="#cb5-13" aria-hidden="true" tabindex="-1"></a><span class="co">          объекты с M &lt; delta (это шум);</span></span>\n<span id="cb5-14"><a href="#cb5-14" aria-hidden="true" tabindex="-1"></a><span class="co">       2) начать множество эталонов с одного объекта на класс -- с максимальным</span></span>\n<span id="cb5-15"><a href="#cb5-15" aria-hidden="true" tabindex="-1"></a><span class="co">          отступом;</span></span>\n<span id="cb5-16"><a href="#cb5-16" aria-hidden="true" tabindex="-1"></a><span class="co">       3) пока доля ошибок правила ближайшего эталона больше max_errors,</span></span>\n<span id="cb5-17"><a href="#cb5-17" aria-hidden="true" tabindex="-1"></a><span class="co">          добавлять ошибочно классифицированный объект (берите тот, у которого</span></span>\n<span id="cb5-18"><a href="#cb5-18" aria-hidden="true" tabindex="-1"></a><span class="co">          отступ по полной выборке наибольший -- он представляет целую область).</span></span>\n<span id="cb5-19"><a href="#cb5-19" aria-hidden="true" tabindex="-1"></a><span class="co">       Возвращает (индексы эталонов, отступы).</span></span>\n<span id="cb5-20"><a href="#cb5-20" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb5-21"><a href="#cb5-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span></code></pre></div>\n</div>\n<div id="cell011" class="cell markdown">\n<h3 id="задание-21-сколько-объектов-на-самом-деле-нужно">Задание 2.1.\nСколько объектов на самом деле нужно</h3>\n<p>Возьмите выборку, испортите метки у части объектов (так бывает в\nреальной разметке) и посмотрите, что отберёт STOLP.</p>\n<p>Важно: обучающая и контрольная части должны быть из одного\nраспределения — порождайте одну выборку и делите её, а не вызывайте\nгенератор дважды с разными <code>random_state</code>.</p>\n</div>\n<div id="cell012" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a>X_all, y_all <span class="op">=</span> make_blobs(n_samples<span class="op">=</span><span class="dv">900</span>, centers<span class="op">=</span><span class="dv">3</span>, cluster_std<span class="op">=</span><span class="fl">2.2</span>,</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a>                          random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a>X_all <span class="op">=</span> StandardScaler().fit_transform(X_all)</span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a>X_st, Xq, y_st, yq <span class="op">=</span> train_test_split(X_all, y_all, train_size<span class="op">=</span><span class="dv">300</span>, stratify<span class="op">=</span>y_all,</span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a>                                      random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a>noise_idx <span class="op">=</span> np.random.default_rng(<span class="dv">0</span>).choice(<span class="bu">len</span>(y_st), <span class="dv">18</span>, replace<span class="op">=</span><span class="va">False</span>)</span>\n<span id="cb6-7"><a href="#cb6-7" aria-hidden="true" tabindex="-1"></a>y_st <span class="op">=</span> y_st.copy()</span>\n<span id="cb6-8"><a href="#cb6-8" aria-hidden="true" tabindex="-1"></a>y_st[noise_idx] <span class="op">=</span> (y_st[noise_idx] <span class="op">+</span> <span class="dv">1</span>) <span class="op">%</span> <span class="dv">3</span></span>\n<span id="cb6-9"><a href="#cb6-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-10"><a href="#cb6-10" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) примените STOLP, выведите число эталонов и сколько среди них</span></span>\n<span id="cb6-11"><a href="#cb6-11" aria-hidden="true" tabindex="-1"></a><span class="co">#          объектов с испорченными метками;</span></span>\n<span id="cb6-12"><a href="#cb6-12" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) сравните точность на ОТЛОЖЕННЫХ данных (Xq, yq): вся выборка</span></span>\n<span id="cb6-13"><a href="#cb6-13" aria-hidden="true" tabindex="-1"></a><span class="co">#          с kNN(5) против правила ближайшего эталона.</span></span></code></pre></div>\n</div>\n<div id="cell013" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте профиль отступов (столбики, упорядоченные по возрастанию M,</span></span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       отрицательные другим цветом) и картинку выборки с отмеченными</span></span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       эталонами и испорченными метками.</span></span></code></pre></div>\n</div>\n<div id="cell014" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Сколько объектов оставил STOLP и как\nизменилась точность? Попали ли испорченные метки в эталоны? Зачем вообще\nотбирать эталоны?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell015" class="cell markdown">\n<h2 id="итоги-домашней-работы">Итоги домашней работы</h2>\n<p>Кратко ответьте на вопросы:</p>\n<ol>\n<li>Все пять методов — частные случаи одной формулы. У какого из них нет\nнастраиваемых параметров вовсе и чем это удобно?</li>\n<li>Вы применили STOLP и получили 3 эталона из 500 при точности 0.95.\nНасколько такому результату можно доверять и что стоит проверить?</li>\n</ol>\n<hr />\n<p>Проверьте перед сдачей: Kernel → Restart &amp; Run All проходит без\nошибок, все ячейки <strong>Вывод</strong> заполнены, графики\nподписаны.</p>\n</div>\n</body>\n</html>\n'}}]);